UNION ALL -- Commission On Receipt SELECT SET_DocumentType.DocumentType, AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, AR_ReceiptTransactionHeader.ReceiptTransactionID as SourceID, ((AR_ReceiptTransactionHeader.Amount * AR_ReceiptTransactionHeader.CommissionPercentage)/100) * -1 as Amount, '0' AS InstrumentNo, IsNull(AR_ReceiptTransactionHeader.Comments, '') + (Case When AR_ReceiptTransactionHeader.ReversalComments IS NULL Then '' Else ' ' + AR_ReceiptTransactionHeader.ReversalComments End) AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(AR_ReceiptTransactionHeader.DocumentNo, 0) AS DocumentNo, AR_ReceiptTransactionHeader.DocumentDate AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN AR_ReceiptTransactionHeader ON SET_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN AR_SET_Customer ON AR_ReceiptTransactionHeader.EmployeeID = AR_SET_Customer.CustomerID --AND AR_ReceiptTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID {7} WHERE AR_SET_Customer.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate --AR_SET_Customer.CompanyID = @CompanyID AND {4} GROUP BY AR_ReceiptTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName, AR_ReceiptTransactionHeader.ReceiptTransactionID, AR_ReceiptTransactionHeader.CommissionPercentage, AR_ReceiptAccountsDetail.ReceiptHeaderID, AR_ReceiptAccountsDetail.ReceiptAccountID,AR_ReceiptAccountsDetail.Amount, AR_ReceiptTransactionHeader.Amount, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptTransactionHeader.DocumentDate, SET_DocumentType.DocumentType, Comments, ReversalComments
