union All SELECT distinct SET_DocumentType.DocumentType, SAL_DiscountTransactionHeader.CreateDate, AR_SET_Customer.CustomerID, AR_SET_Customer.CustomerName AS BusinessPartnerName, SAL_DiscountTransactionHeader.DiscountTransactionHeaderID as SourceID, (SAL_DiscountTransactionHeader.CalculatedAmount * -1) as Amount, '0' AS InstrumentNo, '' AS Comments, '' as InvoiceNumbers, '' as InvoiceDocumentNo, ISNULL(SAL_DiscountTransactionHeader.DiscountTransactionHeaderID, 0) AS DocumentNo, SAL_DiscountTransactionHeader.RunDateTime AS DocumentDate, 0 AS FreightAmount, 0 As ForAlhajAmount FROM SET_DocumentType INNER JOIN SAL_DiscountTransactionHeader ON SET_DocumentType.CompanyID = SAL_DiscountTransactionHeader.CompanyID AND SET_DocumentType.PeriodID = SAL_DiscountTransactionHeader.PeriodID AND SET_DocumentType.DocumentTypeID = SAL_DiscountTransactionHeader.DocumentTypeID INNER JOIN AR_SET_Customer ON SAL_DiscountTransactionHeader.CustomerID = AR_SET_Customer.CustomerID --AND SAL_DiscountTransactionHeader.CompanyID = AR_SET_Customer.CompanyID AND SAL_DiscountTransactionHeader.PeriodID = AR_SET_Customer.PeriodID AND AR_SET_Customer.Status = 1 AND AR_SET_Customer.IsActive = 1 {1} INNER JOIN AR_SET_BusinessPartnerTypes ON AR_SET_BusinessPartnerTypes.BusinessPartnerID = AR_SET_Customer.CustomerID --AND AR_SET_BusinessPartnerTypes.CompanyID = AR_SET_Customer.CompanyID AND AR_SET_BusinessPartnerTypes.PeriodID = AR_SET_Customer.PeriodID {0} INNER JOIN AR_SET_BusinessPartner ON AR_SET_BusinessPartner.BusinessPartnerID = AR_SET_BusinessPartnerTypes.TypeCode {7} WHERE AR_SET_Customer.PeriodID = @PeriodID --AR_SET_Customer.CompanyID = @CompanyID AND AND SAL_DiscountTransactionHeader.RunDateTime BETWEEN @FromDate AND @ToDate
